result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ac_nodal.py", "content": """"AC steady-state nodal solver using complex phasors.

Netlist grammar (one element per line, '#'/'*' start comment lines):

    R name n1 n2 ohms          Resistor
    L name n1 n2 henries       Inductor  -> impedance j*w*L
    C name n1 n2 farads        Capacitor -> impedance 1/(j*w*C)
    V name n1 n2 AC amp [deg]  Independent AC voltage source (phase in degrees,
                               default 0). A bare number also accepted.

Node '0' is ground. Values may be plain floats/scientific notation, or carry
an SI prefix suffix (t, g, meg, k, m, u, n, p), e.g. '10u' == 10e-6.

Modified Nodal Analysis (MNA) is used: unknowns are the complex node voltages
plus one branch-current unknown per voltage source.
"""

from __future__ import annotations

import math
from dataclasses import dataclass, field

import numpy as np

_GROUND = "0"

_PREFIXES = {
    "t": 1e12,
    "g": 1e9,
    "meg": 1e6,
    "k": 1e3,
    "m": 1e-3,
    "u": 1e-6,
    "n": 1e-9,
    "p": 1e-12,
}


@dataclass
class Element:
    kind: str            # 'R', 'L', 'C', or 'V'
    name: str
    n1: str
    n2: str
    value: float         # ohms / henries / farads / volts
    phase_deg: float = 0.0  # only for V


def parse_value(token: str) -> float:
    """Parse a numeric value with optional SI-prefix suffix ('10u', '4meg')."""
    s = token.strip()
    try:
        return float(s)
    except ValueError:
        pass
    for pref in ("meg", "MEG"):
        if s.endswith(pref):
            return float(s[: -len(pref)]) * _PREFIXES["meg"]
    tail = s[-1].lower()
    if tail in _PREFIXES:
        return float(s[:-1]) * _PREFIXES[tail]
    raise ValueError(f"cannot parse value {token!r}")


def parse_netlist(text: str) -> list[Element]:
    """Parse netlist text into a list of Elements."""
    elements: list[Element] = []
    seen: set[str] = set()
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith(("*", "#")):
            continue
        tok = line.split()
        name = tok[0]
        kind = name[0].upper()
        if len(tok) < 4:
            raise ValueError(f"line {lineno}: too few fields: {line!r}")
        n1, n2 = tok[1], tok[2]
        if kind in ("R", "L", "C"):
            if len(tok) != 4:
                raise ValueError(f"line {lineno}: expected 'X name n1 n2 value': {line!r}")
            elements.append(Element(kind, name, n1, n2, parse_value(tok[3])))
        elif kind == "V":
            rest = tok[3:]
            if rest and rest[0].upper() == "AC":
                rest = rest[1:]
            if not (1 <= len(rest) <= 2):
                raise ValueError(
                    f"line {lineno}: expected 'V name n1 n2 AC amp [phase_deg]': {line!r}"
                )
            amp = parse_value(rest[0])
            phase = float(rest[1]) if len(rest) == 2 else 0.0
            elements.append(Element("V", name, n1, n2, amp, phase))
        else:
            raise ValueError(f"line {lineno}: unknown element type {kind!r}")
        if name.lower() in seen:
            raise ValueError(f"duplicate element name {name!r}")
        seen.add(name.lower())
    if not any(el.kind == "V" for el in elements):
        raise ValueError("netlist needs at least one voltage source")
    return elements


@dataclass
class Solution:
    w: float
    volts: dict[str, complex] = field(default_factory=dict)   # node -> phasor
    src_currents: list[complex] = field(default_factory=list)  # per V source,
    # defined as current flowing from n1 THROUGH the source to n2.


def solve_ac(elements: list[Element], w: float) -> Solution:
    """Solve the circuit at angular frequency w [rad/s] (complex MNA)."""
    node_names: list[str] = []
    for el in elements:
        for n in (el.n1, el.n2):
            if n != _GROUND and n not in node_names:
                node_names.append(n)
    idx = {n: i + 1 for i, n in enumerate(node_names)}   # 0 reserved for gnd
    n_nodes = len(node_names)

    vsrcs = [el for el in elements if el.kind == "V"]
    size = n_nodes + len(vsrcs)
    A = np.zeros((size, size), dtype=complex)
    z = np.zeros(size, dtype=complex)

    def ni(node: str) -> int:
        return idx[node] - 1 if node != _GROUND else -1

    def stamp_admit(a: str, b: str, y: complex) -> None:
        ia, ib = ni(a), ni(b)
        if ia >= 0:
            A[ia, ia] += y
            if ib >= 0:
                A[ia, ib] -= y
        if ib >= 0:
            A[ib, ib] += y
            if ia >= 0:
                A[ib, ia] -= y

    for el in elements:
        if el.kind == "R":
            stamp_admit(el.n1, el.n2, 1.0 / el.value)
        elif el.kind == "L":
            stamp_admit(el.n1, el.n2, 1.0 / (1j * w * el.value))
        elif el.kind == "C":
            stamp_admit(el.n1, el.n2, 1j * w * el.value)
        elif el.kind == "V":
            k = n_nodes + vsrcs.index(el)
            ia, ib = ni(el.n1), ni(el.n2)
            if ia >= 0:
                A[ia, k] += 1.0
                A[k, ia] += 1.0
            if ib >= 0:
                A[ib, k] -= 1.0
                A[k, ib] -= 1.0
            z[k] = el.value * np.exp(1j * math.radians(el.phase_deg))
        else:
            raise ValueError(f"unsupported element kind {el.kind!r}")

    x = np.linalg.solve(A, z)

    volts = {_GROUND: 0.0 + 0.0j}
    for name, i in idx.items():
        volts[name] = x[i - 1]
    sol = Solution(w=w, volts=volts)
    sol.src_currents = [x[n_nodes + k] for k in range(len(vsrcs))]
    return sol


def port_solution(elements: list[Element], freq_hz: float, src_name: str | None = None):
    """Drive the circuit with its voltage source at freq_hz and return
    (V_port_phasor, I_port_phasor) where I_port is the current the source
    delivers into the circuit at the source's n1 terminal."""
    src_name_l = src_name.lower() if src_name else None
    vsrcs = [el for el in elements if el.kind == "V"]
    if src_name_l is None:
        src = vsrcs[0]
    else:
        src = next((s for s in vsrcs if s.name.lower() == src_name_l), None)
        if src is None:
            raise KeyError(f"no voltage source named {src_name!r}")

    # Temporarily retune every source's phase/frequency scale: we assume a
    # single-tone circuit; the source amplitude stays fixed, frequency is the
    # independent variable of the sweep.
    w = 2.0 * math.pi * freq_hz
    sol = solve_ac(elements, w)
    k = vsrcs.index(src)
    v_port = src.value * np.exp(1j * math.radians(src.phase_deg))
    i_port = -sol.src_currents[k]  # current delivered into circuit at n1
    return v_port, i_port


def input_impedance(elements: list[Element], freq_hz: float,
                    src_name: str | None = None) -> complex:
    """Small-signal driving-point impedance Z(f) = V_source / I_delivered."""
    v, i = port_solution(elements, freq_hz, src_name)
    return v / i


# ----------------------------------------------------------------------------
# Resonance search: dense scan followed by golden-section refinement
# ----------------------------------------------------------------------------

def _golden_minimize(fn, a: float, b: float, tol: float, max_iter: int = 300) -> float:
    invphi = (math.sqrt(5.0) - 1.0) / 2.0
    c = b - invphi * (b - a)
    d = a + invphi * (b - a)
    fc, fd = fn(c), fn(d)
    for _ in range(max_iter):
        if (b - a) <= tol:
            break
        if fc < fd:
            b, d, fd = d, c, fc
            c = b - invphi * (b - a)
            fc = fn(c)
        else:
            a, c, fc = c, d, fd
            d = a + invphi * (b - a)
            fd = fn(d)
    return 0.5 * (a + b)


def resonant_frequency(elements: list[Element], f_lo: float, f_hi: float,
                       n_scan: int = 4001,
                       rel_tol: float = 1e-9) -> tuple[float, float]:
    """Find f minimizing |Z_in(f)| in [f_lo, f_hi].

    Returns (f_res, |Z|_min). Strategy: dense log-spaced scan to bracket the
    minimum, then golden-section refinement inside the bracketing interval.
    """
    freqs = np.logspace(math.log10(f_lo), math.log10(f_hi), n_scan)
    mags = np.array([abs(input_impedance(elements, f)) for f in freqs])
    i0 = int(np.argmin(mags))
    lo = freqs[max(i0 - 1, 0)]
    hi = freqs[min(i0 + 1, len(freqs) - 1)]
    f_res = _golden_minimize(lambda f: abs(input_impedance(elements, f)),
                             float(lo), float(hi), tol=rel_tol * hi)
    return f_res, abs(input_impedance(elements, f_res))


def current_magnitude(elements: list[Element], freq_hz: float) -> float:
    _, i = port_solution(elements, freq_hz)
    return abs(i)


def current_phase_deg(elements: list[Element], freq_hz: float) -> float:
    """Phase of the delivered current relative to the source voltage [degrees]."""
    v, i = port_solution(elements, freq_hz)
    return math.degrees(np.angle(i / v))


def quality_factor_from_bandwidth(elements: list[Element], f_res: float,
                                  span_low: float = 0.02, span_high: float = 50.0,
                                  xtol: float = 1e-10) -> float:
    """Extract Q from the half-power (|I| = I_max/sqrt(2)) bandwidth:

        Q = f_res / (f2 - f1)

    The half-power points f1 < f_res < f2 are located by bisection.
    """
    i_max = current_magnitude(elements, f_res)
    target = i_max / math.sqrt(2.0)
    g = lambda f: current_magnitude(elements, f) - target

    def bisect(a: float, b: float) -> float:
        ga, gb = g(a), g(b)
        if ga * gb > 0:
            raise RuntimeError("half-power point not bracketed")
        for _ in range(200):
            m = 0.5 * (a + b)
            if (b - a) <= xtol * max(1.0, b):
                break
            gm = g(m)
            if ga * gm <= 0:
                b, gb = m, gm
            else:
                a, ga = m, gm
        return 0.5 * (a + b)

    f1 = bisect(span_low * f_res, f_res)      # rising edge (g < 0 -> g > 0)
    f2 = bisect(f_res, span_high * f_res)     # falling edge (g > 0 -> g < 0)
    return f_res / (f2 - f1)
